INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1631', N'邪神部落', N'负责管理码头的理查德爵士喜爱古董，他最得意的收藏是一只陶罐，这个陶罐年代久远，造型和花纹都不像是梅恩兰德本地的产物。某日地震，陶罐从展示台上落下，摔了个粉碎。伤心的爵士在整理地面的碎片时，发现陶罐的内壁还刻有图案，他好奇地把它们拼在一起，组成了一张地图。地图上标记的地方是远离梅恩兰德大陆的一个岛屿。数日之后，爵士的“梅恩兰德号”停靠在了这个未知岛屿的岸边。岛内到处都是茂密的丛林，爵士带领部下开始搭建营帐，从各地召集而来的勇者早就按捺不住好奇心，分成数个小队进入岛内森林开始了探索……', '1200', '980', '1176', '780', '1200', '980', '10', '2', N'fore', N'back', N'dead', N'', N'', N'2001', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
