INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1627', N'新波谷第七关', N'你们以为刚才杀的是我吗？不不不，那只是我的分身，让你们尝尝我真正的厉害，毁灭世界不在话下。', '1784', '992', '1100', '960', '1784', '992', '10', '2', N'', N'back', N'dead', N'', N'', N'1084', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1626', N'新波谷第六关', N'真没想到你们能战斗到这一刻，我无尽的欲望促使我占据了啵咕世界，原以为人类的世界也会轻易被我占据，可没想到你们的实力大大超出了我的想象，现在我将让你们看到我最终的力量，我绝不能让你们活着回去', '1784', '992', '1100', '960', '1784', '992', '10', '2', N'', N'back', N'dead', N'', N'', N'1084', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1625', N'新波谷第五关', N'在皇宫深处，战士们与史莱姆王展开了激战，这会是最后的战斗吗？还是会是另一场战斗的序幕呢？', '1784', '1292', '1133', '1292', '1784', '1292', '10', '2', N'fore', N'back', N'dead', N'', N'', N'1076', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1624', N'新波谷第四关', N'经过漫长的旅途，战士们来到了皇宫的城门前，神秘的魔法阵挡住了战士们的去路，天上漂浮的木板必有玄机……', '1500', '800', '1100', '791', '1500', '800', '10', '2', N'', N'back', N'dead', N'', N'', N'1075', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
