INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1026', N'Xe lửa', N'Xe lửa trong thế giới Gunny di chuyển trên đường sắt, các GUILD vì muốn có vũ khí mạnh nhất lao vào cướp bóc. Trạm trưởng đã phát thông báo, kêu gọi mọi người tiếp viện. ', '2430', '1134', '1100', '606', '2430', '1134', '10', '2', N'fore', N'back', N'dead', N'', N'', N'1026', N'500,400|600,420|700,440|800,460', '2', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1025', N'Đáy biển', N'Truyền rằng đáy biển Caribe có rất nhiều xác thuyền đắm từ thời cổ đại, ẩn chứa những báu vật kì bí. Là thần dân Gunny, biết tin này không lẽ bạn vẫn ngồi yên được sao? ', '2396', '1038', '1100', '624', '0', '0', '10', '2', N'fore', N'back', N'', N'', N'', N'1025', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
