INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1021', N'Cầu vồng (nhỏ)', N'Một nơi thần kì, mọi thứ đều bí ẩn. Lão kình ngư khổng lồ giữa biển, áng mây ngũ sắc vòng quanh. Đâu đó vài chú hải cẩu vươn mình bên đàn cá. Kìa 1 đám mây hình con mực bị gió thổi lượn vòng quanh lão kình ngư ấy. Những cụm mấy hồng nhỏ bé cứ như đàn cá lượn lờ bơi. ', '1500', '825', '1000', '798', '1500', '825', '10', '2', N'', N'back', N'dead', N'', N'', N'1001', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1020', N'Bờ biển ngà (nhỏ)', N'Trong các kì bình chọn hằng năm " địa điểm đáng tham quan nhất" thì bờ biển ngà luôn chiếm hạng cao trong top. Không chỉ vì phong cảnh đẹp mà còn vì nơi đây mang trên mình truyền thuyết về hải thần. Vũ khí tối thượng của ngài được dấu nơi đây. Có được nó bạn sẽ có sức mạnh phi thường. ', '1351', '962', '1000', '962', '1351', '962', '10', '2', N'', N'back', N'dead', N'', N'', N'1014', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1019', N'Đu quay (nhỏ)', N'Nghe nói，đu quay chở trên mình niềm hạnh phúc. Chúng mình phải cùng người yêu dấu ngồi trên đu quay này, cùng nhau kiếm tìm hạnh phúc. Thật ra thì hạnh phúc cũng giống như đu quay, cứ mãi xoay tròn, không bao giờ ngừng quay...  ', '1540', '895', '1000', '765', '1540', '895', '10', '2', N'', N'back', N'dead', N'', N'', N'1006', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
