INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1012', N'Đèn lồng vàng', N'Quê hương Giang Nam bình lặng, phong cảnh hữu tình khiến ai 1 lần đến sẽ rất khó quên. Bạn đã có duyên đến với nơi này sao không nán lại để cảnh đẹp thu vào trong kí ức. ', '2692', '1477', '1100', '916', '0', '0', '10', '2', N'fore', N'back', N'', N'', N'', N'1012', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1011', N'Thành ác ma', N'Bá tước Dracula, thích mùi máu tươi, sống trong lâu đài cổ kính, người thường không dám bén gót chân. Cẩn thận lũ quạ đen tinh quái luôn chực chờ móc mắt bạn.  ', '2000', '1040', '1242', '1040', '0', '0', '10', '2', N'fore', N'back', N'', N'', N'', N'1011', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1010', N'Dạ đàm', N'Vùng đất này từ xưa đã là 1 thánh địa truyền thuyết. Nếu cùng các thiếu nữ xinh đẹp nơi đây 1 lần chạm mặt, bạn sẽ thấy cuộc đời đầy sinh lực và kì vọng. Những bảo vật đang cất giấu quanh đây cũng đang đi tìm chủ nhân xứng đáng.  
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1009', N'Ba Tư huyền bí', N'“Ta，Vua Ba Tư, vua vĩ đại nhất mọi thời đại, con của cha ta, cháu của ông nội ta”. Dòng dõi quý tộc của ta sẽ mãi trường tồn. ', '2300', '1142', '1000', '796', '0', '0', '10', '2', N'fore', N'back', N'', N'', N'', N'1009', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1008', N'Phố nấm lùn', N'Truyền rằng cùng trời cuối đất có 1 vùng đất lạ, nơi đó tuyệt nhiên không có đấu tranh, là quê hương của niềm hạnh phúc. ——Chính là phố nấm lùn。Ở đây bạn có thể phát huy tiềm lực. Bạn muốn có sức mạnh không? Hãy dùng thực lực để phấn đấu nhé. ', '2000', '1194', '1100', '897', '0', '0', '10', '2', N'fore', N'back', N'', N'', N'', N'1008', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1007', N'Olympus', N'Olympus là thánh địa của các vị thần Hy Lạp. Olympus đi vào lòng người thể hiện ý chí đấu tranh vàsức mạnh phi thường, trở thành di sản văn hóa của lòai người đương đại. ', '2000', '900', '1000', '649', '0', '0', '10', '2', N'fore', N'back', N'', N'', N'', N'1007', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1006', N'Đu quay', N'Nghe nói，đu quay chở trên mình niềm hạnh phúc. Chúng mình phải cùng người yêu dấu ngồi trên đu quay này, cùng nhau kiếm tìm hạnh phúc. Thật ra thì hạnh phúc cũng giống như đu quay, cứ mãi xoay tròn, không bao giờ ngừng quay...  ', '2200', '1278', '1100', '841', '2200', '1278', '10', '2', N'fore', N'back', N'dead', N'', N'', N'1006', N'500,400|600,420|700,440|800,460', '2', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1005', N'Rừng nhiệt đới', N'Rừng nhiệt đới sở hữu thảm thực vật vô cùng phong phú, với những cây dây leo chằng chịt và các loài cây cỏ to lớn. Tất cả tạo nên khu rừng kín bưng huyền bí, ẩm ướt và nguy hiểm. Thám hiểm rừng chớ áp sát cây rừng, cẩn thận lũ khỉ tinh nghịch.  ', '1300', '948', '1138', '948', '0', '0', '10', '2', N'fore', N'back', N'', N'', N'', N'1005', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1004', N'Lớp học ma thuật', N'Lớp học này có từ xa xưa, chế tác hoàn toàn từ gỗ, hầu như không thấy bạn nhỏ nào đến học. Bàn ghế, bảng đen, phấn viết lợi dụng lúc không người cãi nhau loạn xạ. Lại có nhiều sách ma thuật dày cộm, hình như đã rất lâu đời. Mấy tên người giấy thòi đầu ra khỏi bìa sách, khát khao tự do.  
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1003', N'Công trường', N'Các kĩ sư của chúng ta đangkhẩn trương để kịp tiến độ công trình.Nán lại nơi này thì bảo đảm bạn sẽ bắt gặp vật thể lạ từ trên trời rơi xuống, nếu là UFO thì còn gì bằng. ', '1272', '950', '1139', '950', '1272', '950', '10', '2', N'fore', N'back', N'dead', N'', N'', N'1003', N'500,400|600,420|700,440|800,460', '2', N'500,400|600,420|700,440|800,460');
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1002', N'Đường bay ma quái', N'Chúng tôi đứng bên cột buồm nhìn xa xăm: Trên boong tàu đầy ắp châu báu của hải tặc.Toàn thứ quý hiếm. Lại còn có rượu thịt ê hề. Tôi vừa thấy bên thùng rượu là 1 bộ xương tay cầm kim bôi. Bánh lái khổng lồ, dây thừng chắc chắn. Những thứ này lại không quan trọng bằng việc bạn đánh bại được đối thủ, đây là chiến lợi phẩm và bạn đang lênh đênh trên biển, vượt qua thử thách trùng trùng.
INSERT INTO [Game_Map] ([ID],[Name],[Description],[ForegroundWidth],[ForegroundHeight],[BackroundWidht],[BackroundHeight],[DeadWidth],[DeadHeight],[Weight],[DragIndex],[ForePic],[BackPic],[DeadPic],[Pic],[Remark],[BackMusic],[PosX],[Type],[PosX1])  VALUES ('1001', N'Cầu vồng', N'Một nơi thần kì, mọi thứ đều bí ẩn. Lão kình ngư khổng lồ giữa biển, áng mây ngũ sắc vòng quanh. Đâu đó vài chú hải cẩu vươn mình bên đàn cá. Kìa 1 đám mây hình con mực bị gió thổi lượn vòng quanh lão kình ngư ấy. Những cụm mấy hồng nhỏ bé cứ như đàn cá lượn lờ bơi. ', '2000', '1425', '1526', '1425', '0', '0', '10', '2', N'fore', N'back', N'', N'test', N'', N'1001', N'500,400|600,420|700,440|800,460', '3', N'500,400|600,420|700,440|800,460');
